const $=id=>document.getElementById(id),canvas=$('card'),ctx=canvas.getContext('2d'),photo=new Image();let ready=false,list=[],index=0;
function currentName(){return $('name').value.trim().replace(/\s+/g,' ')}
function paint(){if(!ready)return;ctx.clearRect(0,0,870,1175);ctx.drawImage(photo,0,0,870,1175);const name=currentName();let size=Number($('size').value);const style=$('font').value==='italic'?'italic ':'';ctx.font=style+size+'px Georgia, serif';while(ctx.measureText(name).width>455&&size>12){size--;ctx.font=style+size+'px Georgia, serif'}ctx.fillStyle='#161616';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(name,520,443);$('download').disabled=!name;$('share').disabled=!name;$('status').textContent=name?'Your personalized card is ready.':'Enter a guest’s name to get started.'}
photo.onload=()=>{ready=true;paint()};photo.onerror=()=>{$('status').textContent='The card could not load. Please refresh to try again.'};photo.src='card.png';
for(const id of ['name','font','size'])$(id).addEventListener('input',paint);
function blob(){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Could not create the image.')),'image/png'))}
function filename(){return 'Rita-Shepherd-'+(currentName().replace(/[^\p{L}\p{N}]+/gu,'-').slice(0,70)||'invitation')+'.png'}
$('download').onclick=async()=>{try{const url=URL.createObjectURL(await blob());const a=document.createElement('a');a.href=url;a.download=filename();a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('status').textContent='Invitation downloaded. Ready for the next guest.'}catch(e){$('status').textContent='Could not download. Please try again.'}};
if(navigator.canShare){$('share').hidden=false;$('share').onclick=async()=>{try{const file=new File([await blob()],filename(),{type:'image/png'});if(navigator.canShare({files:[file]}))await navigator.share({files:[file],title:'Rita & Shepherd’s Introduction'});else $('status').textContent='Use Download invitation, then share the saved image.'}catch(e){if(e.name!=='AbortError')$('status').textContent='Use Download invitation, then share the saved image.'}}}
function selectGuest(){ $('name').value=list[index];$('counter').textContent=`Guest ${index+1} of ${list.length}`;$('prev').disabled=index===0;$('next').disabled=index===list.length-1;paint() }
$('load').onclick=()=>{list=$('guests').value.split(/\r?\n/).map(n=>n.trim().slice(0,100)).filter(Boolean);if(!list.length){$('status').textContent='Add at least one name to the guest list.';return}index=0;$('queue').hidden=false;selectGuest()};$('prev').onclick=()=>{if(index>0){index--;selectGuest()}};$('next').onclick=()=>{if(index<list.length-1){index++;selectGuest()}};

const mobileLayout=window.matchMedia("(max-width:760px)"),preview=document.querySelector(".preview");
function positionPreview(){if(mobileLayout.matches){$("download").before(preview)}else{document.querySelector("main").append(preview)}}
mobileLayout.addEventListener("change",positionPreview);positionPreview();
